# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

torch::Tensor lstm_hn_forward(
    torch::Tensor x,
    torch::Tensor h0,
    torch::Tensor c0,
    std::vector<torch::Tensor> weight_ih,
    std::vector<torch::Tensor> weight_hh,
    std::vector<torch::Tensor> bias_ih,
    std::vector<torch::Tensor> bias_hh
) {
    // x: (batch, seq, input_size), batch_first=True
    // h0, c0: (num_layers, batch, hidden_size)
    int num_layers = (int)weight_ih.size();
    int batch_size = x.size(0);
    int seq_len    = x.size(1);
    int hidden_size = (int)weight_hh[0].size(1);

    // Output tensor for h_n: (num_layers, batch, hidden)
    auto opts = x.options();
    torch::Tensor h_n = torch::empty({num_layers, batch_size, hidden_size}, opts);

    // layer_input holds the sequence for the current layer: (batch, seq, feat)
    torch::Tensor layer_input = x;

    for (int layer = 0; layer < num_layers; layer++) {
        int in_features = (int)weight_ih[layer].size(1); // input_size for this layer

        // Precompute input projection for all timesteps at once:
        // flat_input: (batch*seq, in_features)
        auto flat_input = layer_input.reshape({batch_size * seq_len, in_features});
        // gates_x: (batch*seq, 4*hidden) = flat_input @ weight_ih[layer].T + bias_ih[layer]
        // at::addmm broadcasts bias (1D) as row bias
        auto gates_x_flat = at::addmm(
            bias_ih[layer].unsqueeze(0).expand({batch_size * seq_len, 4 * hidden_size}),
            flat_input,
            weight_ih[layer].t()
        );
        // gates_x: (batch, seq, 4*hidden)
        auto gates_x = gates_x_flat.reshape({batch_size, seq_len, 4 * hidden_size});

        // Initialize h_t and c_t for this layer
        auto h_t = h0[layer];  // (batch, hidden)
        auto c_t = c0[layer];  // (batch, hidden)

        // Allocate output sequence buffer for next layer: (batch, seq, hidden)
        torch::Tensor layer_output = torch::empty({batch_size, seq_len, hidden_size}, opts);

        // Recurrent loop: only hidden-to-hidden projection inside
        for (int t = 0; t < seq_len; t++) {
            // gates_h: (batch, 4*hidden) = h_t @ weight_hh[layer].T + bias_hh[layer]
            auto gates_h = at::addmm(
                bias_hh[layer],
                h_t,
                weight_hh[layer].t()
            );
            // Combine with precomputed input gates
            auto gates = gates_x.select(1, t) + gates_h;  // (batch, 4*hidden)

            // Split into i, f, g, o gates (PyTorch order: i, f, g, o)
            auto i_gate = gates.slice(1, 0,           hidden_size).sigmoid();
            auto f_gate = gates.slice(1, hidden_size,   2*hidden_size).sigmoid();
            auto g_gate = gates.slice(1, 2*hidden_size, 3*hidden_size).tanh();
            auto o_gate = gates.slice(1, 3*hidden_size, 4*hidden_size).sigmoid();

            // Update cell and hidden states
            c_t = f_gate * c_t + i_gate * g_gate;
            h_t = o_gate * c_t.tanh();

            layer_output.select(1, t).copy_(h_t);
        }

        // Store final hidden state for this layer
        h_n[layer].copy_(h_t);

        // Output of this layer becomes input to next layer
        layer_input = layer_output;
    }

    return h_n;
}
