# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <vector>

// CUDA kernel: given precomputed x_proj[t] (batch x 4*hidden) and h_proj (batch x 4*hidden),
// add biases, apply LSTM gates, update c and h in-place.
__global__ void lstm_cell_kernel(
    const float* __restrict__ x_proj_t,  // [batch, 4*hidden]
    const float* __restrict__ h_proj_t,  // [batch, 4*hidden]
    const float* __restrict__ b_ih,      // [4*hidden]
    const float* __restrict__ b_hh,      // [4*hidden]
    float* __restrict__ h,               // [batch, hidden]
    float* __restrict__ c,               // [batch, hidden]
    int batch_size,
    int hidden_size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * hidden_size;
    if (idx >= total) return;

    int b = idx / hidden_size;
    int j = idx % hidden_size;
    int g4 = 4 * hidden_size;

    // Gate indices follow PyTorch LSTM order: i, f, g, o
    float i_gate = x_proj_t[b * g4 + j]              + h_proj_t[b * g4 + j]              + b_ih[j]              + b_hh[j];
    float f_gate = x_proj_t[b * g4 + hidden_size + j] + h_proj_t[b * g4 + hidden_size + j] + b_ih[hidden_size + j] + b_hh[hidden_size + j];
    float g_gate = x_proj_t[b * g4 + 2*hidden_size + j] + h_proj_t[b * g4 + 2*hidden_size + j] + b_ih[2*hidden_size + j] + b_hh[2*hidden_size + j];
    float o_gate = x_proj_t[b * g4 + 3*hidden_size + j] + h_proj_t[b * g4 + 3*hidden_size + j] + b_ih[3*hidden_size + j] + b_hh[3*hidden_size + j];

    // Activations
    float i_act = 1.0f / (1.0f + __expf(-i_gate));
    float f_act = 1.0f / (1.0f + __expf(-f_gate));
    float g_act = tanhf(g_gate);
    float o_act = 1.0f / (1.0f + __expf(-o_gate));

    float c_new = f_act * c[b * hidden_size + j] + i_act * g_act;
    float h_new = o_act * tanhf(c_new);

    c[b * hidden_size + j] = c_new;
    h[b * hidden_size + j] = h_new;
}

torch::Tensor lstm_hn_only(
    torch::Tensor x,       // [batch, seq, input_size] batch_first
    torch::Tensor h0,      // [num_layers, batch, hidden]
    torch::Tensor c0,      // [num_layers, batch, hidden]
    std::vector<torch::Tensor> w_ih,  // per layer [4*hidden, input_or_hidden]
    std::vector<torch::Tensor> w_hh,  // per layer [4*hidden, hidden]
    std::vector<torch::Tensor> b_ih,  // per layer [4*hidden]
    std::vector<torch::Tensor> b_hh   // per layer [4*hidden]
) {
    int num_layers = (int)w_ih.size();
    int batch_size = x.size(0);
    int seq_len    = x.size(1);
    int hidden_size = (int)w_hh[0].size(1);

    // Make sure everything is contiguous on CUDA
    x = x.contiguous();
    h0 = h0.contiguous();
    c0 = c0.contiguous();

    // h_all: [num_layers, batch, hidden] - final hidden states
    auto h_all = h0.clone();
    auto c_all = c0.clone();

    // layer_input starts as x reshaped to [batch*seq, input_size]
    // For upper layers it becomes [batch*seq, hidden_size]
    torch::Tensor layer_input = x.view({batch_size * seq_len, x.size(2)});

    for (int layer = 0; layer < num_layers; layer++) {
        auto wih = w_ih[layer].contiguous();  // [4*hidden, input_size_for_layer]
        auto whh = w_hh[layer].contiguous();  // [4*hidden, hidden]
        auto bih = b_ih[layer].contiguous();  // [4*hidden]
        auto bhh = b_hh[layer].contiguous();  // [4*hidden]

        // Precompute input projection for all timesteps at once:
        // x_proj: [batch*seq, 4*hidden]
        auto x_proj = at::matmul(layer_input, wih.t());  // [batch*seq, 4*hidden]
        // Reshape to [seq, batch, 4*hidden] for easy timestep indexing
        x_proj = x_proj.view({seq_len, batch_size, 4 * hidden_size}).contiguous();

        // Get initial h and c for this layer: [batch, hidden]
        auto h_t = h_all[layer].clone();  // [batch, hidden]
        auto c_t = c_all[layer].clone();  // [batch, hidden]

        int threads = 256;
        int blocks = (batch_size * hidden_size + threads - 1) / threads;

        for (int t = 0; t < seq_len; t++) {
            // h_proj for this timestep: [batch, 4*hidden]
            auto h_proj = at::matmul(h_t, whh.t()).contiguous();  // [batch, 4*hidden]
            auto x_proj_t = x_proj[t].contiguous();               // [batch, 4*hidden]

            lstm_cell_kernel<<<blocks, threads>>>(
                x_proj_t.data_ptr<float>(),
                h_proj.data_ptr<float>(),
                bih.data_ptr<float>(),
                bhh.data_ptr<float>(),
                h_t.data_ptr<float>(),
                c_t.data_ptr<float>(),
                batch_size,
                hidden_size
            );
        }

        // Store final hidden/cell for this layer
        h_all[layer].copy_(h_t);
        c_all[layer].copy_(c_t);

        // Output of this layer becomes input for the next
        // We need to collect all timestep outputs; rebuild from scratch
        // Actually we need the full sequence output for the next layer.
        // Re-run to collect sequence output for chaining layers.
        if (layer < num_layers - 1) {
            // Re-run with sequence collection
            auto h_seq = h0[layer].clone().contiguous();  // [batch, hidden]
            auto c_seq = c0[layer].clone().contiguous();  // [batch, hidden]
            // Output sequence: [seq, batch, hidden]
            auto seq_out = torch::empty({seq_len, batch_size, hidden_size},
                                        x.options());

            for (int t = 0; t < seq_len; t++) {
                auto h_proj2 = at::matmul(h_seq, whh.t()).contiguous();
                auto x_proj_t2 = x_proj[t].contiguous();

                lstm_cell_kernel<<<blocks, threads>>>(
                    x_proj_t2.data_ptr<float>(),
                    h_proj2.data_ptr<float>(),
                    bih.data_ptr<float>(),
                    bhh.data_ptr<float>(),
                    h_seq.data_ptr<float>(),
                    c_seq.data_ptr<float>(),
                    batch_size,
                    hidden_size
                );
                seq_out[t].copy_(h_seq);
            }
            // Next layer input: [batch*seq, hidden]
            layer_input = seq_out.view({seq_len * batch_size, hidden_size}).contiguous();
        }
    }

    return h_all;
}
# <<<END_IMPROVE>>>
"""

